// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    address immutable deployer = address(this);

    function setUp() public {
        c = new ERCDDAToken(1000, "Test", "TST");
    }

    function testFuzz_property(address newOwner, uint256 burnAmount) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != deployer);

        vm.prank(deployer);
        if (burnAmount > c.totalSupply()) {
            return;
        }
        vm.prank(deployer);
        try c.burn(burnAmount) {} catch {}

        vm.prank(deployer);
        c.owned();
        vm.prank(newOwner);
        try c.owned() {} catch {}

        assertTrue(c.owner() == deployer);
    }
}
